const lessons = [
  {id:"cpp1",course:"cpp",title:"Tu primera línea de código",short:"Salida por pantalla",duration:"35–45 min",difficulty:"Principiante",summary:"Conoce la estructura mínima de un programa y aprende a mostrar mensajes en la consola.",concept:"Un programa es una lista de instrucciones que la computadora sigue. En C++, `#include <iostream>` permite usar la entrada y salida, `main()` es el punto de inicio y `cout` muestra texto.",example:'#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << "Hola mundo" << endl;\n    return 0;\n}',phases:[
    {name:"Aprende",type:"learn",title:"¿Cómo empieza un programa?",body:"C++ necesita una función principal llamada `main()`. Las instrucciones que escribes dentro de sus llaves se ejecutan cuando inicia el programa.",box:"Piensa en `cout` como una pantalla donde tu programa puede escribir. El texto va entre comillas y cada instrucción normalmente termina con punto y coma.",items:[["#include <iostream>","Permite utilizar cout y cin."],["int main()","Define el punto de entrada del programa."],["cout << \"Hola\";","Muestra texto en la consola."],["return 0;","Indica que el programa terminó correctamente."]]},
    {name:"Construye",type:"exercise",title:"Tu saludo de programador",body:"Escribe un programa completo que muestre dos líneas: tu nombre o apodo y el texto Estoy aprendiendo C++.",requirements:["Incluye la biblioteca iostream.","Crea la función main().","Muestra dos líneas con cout.","Cierra las instrucciones con punto y coma."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Escribe tu código aquí\n\n    return 0;\n}',hint:"Usa cout << \"Tu texto\" << endl; para cada línea. No olvides escribir los textos entre comillas.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Angel\" << endl;\n    cout << \"Estoy aprendiendo C++\" << endl;\n    return 0;\n}',checks:[["#include\\s*<iostream>","Incluye iostream."],["int\\s+main\\s*\\(","Define main()."],["cout\\s*<<","Usa cout para mostrar texto."],["Estoy aprendiendo C\\+\\+","Muestra el mensaje solicitado."],["return\\s+0\\s*;","Termina main correctamente."]]},
    {name:"Modifica",type:"exercise",title:"Cambia el programa",body:"Aquí tienes un programa casi terminado. Modifícalo para que muestre tres líneas: Lazarus Academy, Aprendo practicando y Sesión 1 completada.",requirements:["Mantén la estructura de main().","Muestra exactamente los tres mensajes solicitados en el código.","Usa cout para las tres líneas."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Hola\" << endl;\n    cout << \"C++\" << endl;\n    return 0;\n}',hint:"Puedes cambiar los textos existentes y añadir una tercera instrucción cout.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Lazarus Academy\" << endl;\n    cout << \"Aprendo practicando\" << endl;\n    cout << \"Sesion 1 completada\" << endl;\n    return 0;\n}',checks:[["Lazarus Academy","Muestra Lazarus Academy."],["Aprendo practicando","Muestra Aprendo practicando."],["Sesion 1 completada|Sesión 1 completada","Muestra el tercer mensaje."],["cout\\s*<<","Usa cout."],["int\\s+main\\s*\\(","Mantiene main()."]]},
    {name:"Depura",type:"exercise",title:"Encuentra los errores",body:"Este código contiene errores intencionales. Corrígelo para que sea un programa válido que muestre Hola, mundo.",requirements:["Corrige la biblioteca mal escrita.","Corrige la instrucción cout.","Completa la estructura de main()."],starter:'#include <iostrem>\nusing namespace std;\n\nint main() {\n    cout < \"Hola, mundo\" << endl\n    return 0\n}',hint:"Compara la biblioteca con iostream. cout necesita dos signos < y las instrucciones necesitan punto y coma.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Hola, mundo\" << endl;\n    return 0;\n}',checks:[["#include\\s*<iostream>","Corrige iostream."],["cout\\s*<<\\s*[\"']Hola, mundo[\"']","Corrige cout y el mensaje."],["endl\\s*;","Añade el punto y coma después de endl."],["return\\s+0\\s*;","Añade el punto y coma a return."]]},
    {name:"Desafío",type:"exercise",title:"Tu tarjeta en consola",body:"Crea desde cero una tarjeta de presentación que muestre tu nombre, tu especialidad y tu meta de aprendizaje. Debe tener al menos tres líneas de salida.",requirements:["Escribe el programa completo.","Muestra al menos tres líneas usando cout.","Incluye un mensaje relacionado con programación o bases de datos."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Diseña tu tarjeta aquí\n\n    return 0;\n}',hint:"Planea primero qué tres datos quieres mostrar. Cada cout puede imprimir una línea diferente.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    cout << \"Nombre: Angel\" << endl;\n    cout << \"Especialidad: Informatica\" << endl;\n    cout << \"Meta: dominar la programacion\" << endl;\n    return 0;\n}',checks:[["#include\\s*<iostream>","Incluye iostream."],["int\\s+main\\s*\\(","Incluye main()."],["cout\\s*<<","Utiliza cout."],["cout\\s*<<.*endl","Usa saltos de línea."],["return\\s+0\\s*;","Cierra correctamente el programa."]]}
  ]},
  {id:"cpp2",course:"cpp",title:"Variables y tipos de datos",short:"Guarda información",duration:"40–55 min",difficulty:"Principiante",summary:"Aprende a guardar números y texto en variables y a mostrar sus valores.",concept:"Una variable es un espacio con nombre donde guardas un dato. `int` guarda enteros, `double` números decimales y `string` texto. Declara la variable antes de utilizarla.",example:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    int edad = 16, nivel = 1;\n    string nombre = "Angel";\n    cout << nombre << endl;\n    cout << edad << endl;\n    return 0;\n}',phases:[
    {name:"Aprende",type:"learn",title:"Variables: datos con nombre",body:"Las variables permiten guardar datos y reutilizarlos. El tipo de dato define qué clase de información contiene. El nombre debe ser claro y no puede tener espacios.",box:"Declara variables del mismo tipo en una sola línea si tiene sentido: `int edad, cantidad;`. Para tipos distintos, usa líneas separadas.",items:[["int","Números enteros, como 16."],["double","Números decimales, como 3.5."],["string","Texto, como \"Angel\". Necesita #include <string>."],["= y ;","El signo = asigna un valor; el punto y coma termina la instrucción."]]},
    {name:"Construye",type:"exercise",title:"Ficha de estudiante",body:"Crea variables para guardar una edad, un grado y un nombre. Después muestra los tres valores con cout.",requirements:["Declara edad y grado como int en la misma línea.","Declara nombre como string.","Asigna valores a las tres variables.","Muestra las variables con cout."],starter:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    // Declara las variables\n\n    // Muestra los valores\n    return 0;\n}',hint:"Puedes escribir `int edad = 16, grado = 12;` y luego `string nombre = \"Angel\";`.",solution:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    int edad = 16, grado = 12;\n    string nombre = \"Angel\";\n    cout << nombre << endl;\n    cout << edad << endl;\n    cout << grado << endl;\n    return 0;\n}',checks:[["int\\s+[^;]*edad","Declara una variable edad de tipo int."],["int\\s+[^;]*grado","Declara grado como int."],["string\\s+\\w+","Declara una variable string."],["cout\\s*<<","Muestra los datos con cout."],["return\\s+0\\s*;","Termina el programa."]]},
    {name:"Modifica",type:"exercise",title:"Actualiza los datos",body:"Modifica el programa para que guarde el nombre de un estudiante, dos calificaciones decimales y muestre las tres variables.",requirements:["Usa string para el nombre.","Usa double para las dos calificaciones.","Declara las dos calificaciones en la misma línea.","Muestra los tres valores."],starter:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string nombre = \"Luis\";\n    int nota = 80;\n    cout << nombre << endl;\n    cout << nota << endl;\n    return 0;\n}',hint:"Cambia int nota por dos variables double. Por ejemplo: `double nota1 = 85.5, nota2 = 92.0;`",solution:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string nombre = \"Luis\";\n    double nota1 = 85.5, nota2 = 92.0;\n    cout << nombre << endl;\n    cout << nota1 << endl;\n    cout << nota2 << endl;\n    return 0;\n}',checks:[["string\\s+\\w+","Usa string para el nombre."],["double\\s+[^;]*nota1","Declara nota1 como double."],["double\\s+[^;]*nota2","Declara nota2 como double."],["cout\\s*<<","Muestra las variables."],["return\\s+0\\s*;","Cierra el programa."]]},
    {name:"Depura",type:"exercise",title:"Tipos y nombres",body:"Corrige este código: el tipo de texto está mal escrito, la variable edad no tiene asignación válida y falta un punto y coma.",requirements:["Corrige el tipo de dato para el nombre.","Corrige la asignación de edad.","Asegura que ambas variables se muestren."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    strng nombre = \"Mia\";\n    int edad = 16\n    cout << nombre << endl;\n    cout << edad << endl;\n    return 0;\n}',hint:"El tipo correcto es string (recuerda incluir <string>). Cada declaración necesita terminar con ;",solution:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string nombre = \"Mia\";\n    int edad = 16;\n    cout << nombre << endl;\n    cout << edad << endl;\n    return 0;\n}',checks:[["#include\\s*<string>","Incluye la biblioteca string."],["string\\s+nombre","Corrige el tipo de nombre."],["int\\s+edad\\s*=\\s*\\d+\\s*;","Corrige edad y su punto y coma."],["cout\\s*<<\\s*nombre","Muestra el nombre."],["cout\\s*<<\\s*edad","Muestra la edad."]]},
    {name:"Desafío",type:"exercise",title:"Calculadora de presupuesto",body:"Declara variables para el precio de un artículo y la cantidad que comprarás. Calcula el total y muestra el resultado.",requirements:["Usa double para el precio.","Usa int para la cantidad.","Calcula total multiplicando precio por cantidad.","Muestra el total con cout."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Declara precio, cantidad y total\n\n    // Calcula y muestra el total\n    return 0;\n}',hint:"La operación puede ser `total = precio * cantidad;`. El tipo de total puede ser double.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    double precio = 25.5, total;\n    int cantidad = 3;\n    total = precio * cantidad;\n    cout << total << endl;\n    return 0;\n}',checks:[["double\\s+[^;]*precio","Declara el precio como double."],["int\\s+[^;]*cantidad","Declara la cantidad como int."],["total\\s*=\\s*[^;]*\\*","Multiplica precio por cantidad."],["cout\\s*<<\\s*total","Muestra el total."],["return\\s+0\\s*;","Cierra el programa."]]}
  ]},
  {id:"cpp3",course:"cpp",title:"Entrada de datos",short:"Usa cin",duration:"40–55 min",difficulty:"Principiante",summary:"Haz que el programa reciba datos de la persona que lo usa.",concept:"`cin` lee información que la persona escribe en la consola. `cout` pregunta o muestra resultados; `cin >> variable` guarda la respuesta en una variable.",example:'int edad;\ncout << "Escribe tu edad: ";\ncin >> edad;\ncout << "Tu edad es " << edad << endl;',phases:[
    {name:"Aprende",type:"learn",title:"Tu programa puede preguntar",body:"Hasta ahora tu programa solo mostraba mensajes. Con `cin` puedes pedir un dato, guardarlo y usarlo después. La variable debe existir antes de leerla.",box:"El orden habitual es: declarar la variable, mostrar la pregunta, leer con cin y mostrar o procesar el valor.",items:[["cout","Muestra la pregunta."],["cin >> edad;","Lee un valor y lo guarda en edad."],["int edad;","Declara la variable antes de usarla."],["<< y >>","cout usa <<; cin usa >>."]]},
    {name:"Construye",type:"exercise",title:"Pregunta el nombre y la edad",body:"Escribe un programa que solicite un nombre y una edad, lea ambos datos y los muestre.",requirements:["Incluye iostream y string.","Declara nombre como string y edad como int.","Lee ambos datos con cin.","Muestra ambos datos con cout."],starter:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    // Declara nombre y edad\n    // Pide y lee los datos\n    // Muestra los datos\n    return 0;\n}',hint:"Usa `cin >> nombre;` y `cin >> edad;`. Para este ejercicio, escribe el nombre sin espacios.",solution:'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    string nombre;\n    int edad;\n    cout << \"Nombre: \";\n    cin >> nombre;\n    cout << \"Edad: \";\n    cin >> edad;\n    cout << nombre << endl;\n    cout << edad << endl;\n    return 0;\n}',checks:[["string\\s+nombre","Declara nombre como string."],["int\\s+edad","Declara edad como int."],["cin\\s*>>\\s*nombre","Lee el nombre."],["cin\\s*>>\\s*edad","Lee la edad."],["cout\\s*<<","Muestra los datos."]]},
    {name:"Modifica",type:"exercise",title:"Calcula el año aproximado de nacimiento",body:"Parte de un programa que lee la edad. Añade una variable para el año actual, calcula añoActual - edad y muestra el resultado aproximado.",requirements:["Lee edad usando cin.","Declara añoActual y nacimiento como int.","Calcula nacimiento = anioActual - edad.","Muestra nacimiento con cout."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int edad;\n    cout << \"Edad: \";\n    cin >> edad;\n    return 0;\n}',hint:"Usa nombres sin tildes en las variables: `int anioActual = 2026, nacimiento;`",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int edad, nacimiento;\n    int anioActual = 2026;\n    cout << \"Edad: \";\n    cin >> edad;\n    nacimiento = anioActual - edad;\n    cout << nacimiento << endl;\n    return 0;\n}',checks:[["cin\\s*>>\\s*edad","Lee la edad."],["anioActual","Declara o utiliza el año actual."],["nacimiento\\s*=\\s*[^;]*-\\s*edad","Calcula el año aproximado."],["cout\\s*<<\\s*nacimiento","Muestra el resultado."]]},
    {name:"Depura",type:"exercise",title:"Corrige la entrada",body:"El programa intenta leer dos números y sumarlos, pero tiene operadores incorrectos y no muestra el resultado. Repara el código.",requirements:["Corrige el operador de cin.","Declara la variable suma.","Calcula a + b.","Muestra la suma."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b;\n    cin << a;\n    cin << b;\n    suma = a + b\n    return 0;\n}',hint:"cin utiliza >>. Declara `int suma;` y no olvides el punto y coma después de la operación.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b, suma;\n    cin >> a;\n    cin >> b;\n    suma = a + b;\n    cout << suma << endl;\n    return 0;\n}',checks:[["cin\\s*>>\\s*a","Corrige la lectura de a."],["cin\\s*>>\\s*b","Corrige la lectura de b."],["int\\s+[^;]*suma","Declara suma."],["suma\\s*=\\s*a\\s*\\+\\s*b\\s*;","Calcula la suma correctamente."],["cout\\s*<<\\s*suma","Muestra la suma."]]},
    {name:"Desafío",type:"exercise",title:"Mini calculadora",body:"Crea un programa que lea dos números enteros, calcule su suma y su producto, y muestre ambos resultados.",requirements:["Declara dos números y dos resultados.","Lee los dos números con cin.","Calcula suma y producto.","Muestra los dos resultados."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Diseña tu calculadora\n    return 0;\n}',hint:"Declara `int a, b, suma, producto;`. Después lee a y b, calcula las dos operaciones y muestra cada resultado.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a, b, suma, producto;\n    cin >> a >> b;\n    suma = a + b;\n    producto = a * b;\n    cout << suma << endl;\n    cout << producto << endl;\n    return 0;\n}',checks:[["int\\s+[^;]*a[^;]*b","Declara dos variables enteras."],["cin\\s*>>","Lee datos con cin."],["suma\\s*=\\s*[^;]*\\+","Calcula la suma."],["producto\\s*=\\s*[^;]*\\*","Calcula el producto."],["cout\\s*<<","Muestra los resultados."]]}
  ]},
  {id:"cpp4",course:"cpp",title:"Decisiones con if y else",short:"Condiciones",duration:"45–60 min",difficulty:"Principiante+",summary:"Haz que el programa tome decisiones según los datos que recibe.",concept:"Una condición permite ejecutar código solo cuando una expresión es verdadera. `if` evalúa una condición; `else` se ejecuta cuando no se cumple.",example:'int edad;\ncin >> edad;\nif (edad >= 18) {\n    cout << "Mayor de edad";\n} else {\n    cout << "Menor de edad";\n}',phases:[
    {name:"Aprende",type:"learn",title:"Tu código puede decidir",body:"Los operadores de comparación permiten comparar valores. `==` significa igual a; `>=` mayor o igual; `<=` menor o igual; `!=` diferente. No confundas `=` (asignación) con `==` (comparación).",box:"Una condición de if va entre paréntesis. Las instrucciones que dependen de ella se escriben entre llaves.",items:[["if (nota >= 60)","Comprueba si nota es al menos 60."],["else","Ejecuta una alternativa si la condición es falsa."],["==","Compara igualdad."],["&& / ||","Representan Y / O lógico."]]},
    {name:"Construye",type:"exercise",title:"¿Aprobó o reprobó?",body:"Lee una calificación. Si es mayor o igual a 60, muestra Aprobado; en caso contrario, muestra Reprobado.",requirements:["Lee una variable int llamada nota.","Usa if con nota >= 60.","Incluye else.","Muestra ambos mensajes posibles."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int nota;\n    cin >> nota;\n    // Escribe la condición\n    return 0;\n}',hint:"La estructura es `if (nota >= 60) { ... } else { ... }`.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int nota;\n    cin >> nota;\n    if (nota >= 60) {\n        cout << \"Aprobado\";\n    } else {\n        cout << \"Reprobado\";\n    }\n    return 0;\n}',checks:[["cin\\s*>>\\s*nota","Lee la nota."],["if\\s*\\(\\s*nota\\s*>=\\s*60\\s*\\)","Comprueba la nota mínima."],["else","Incluye una alternativa."],["Aprobado","Muestra Aprobado."],["Reprobado","Muestra Reprobado."]]},
    {name:"Modifica",type:"exercise",title:"Clasifica un número",body:"Modifica el programa para indicar si un número es positivo o cero/negativo. Lee el número y usa if/else.",requirements:["Lee un entero.","Usa una condición mayor que cero.","Muestra Positivo y No positivo.","Incluye else."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int numero;\n    cin >> numero;\n    if (numero > 10) {\n        cout << \"Grande\";\n    } else {\n        cout << \"Pequeno\";\n    }\n    return 0;\n}',hint:"Cambia la condición a `numero > 0` y adapta los dos mensajes.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int numero;\n    cin >> numero;\n    if (numero > 0) {\n        cout << \"Positivo\";\n    } else {\n        cout << \"No positivo\";\n    }\n    return 0;\n}',checks:[["cin\\s*>>\\s*numero","Lee el número."],["if\\s*\\(\\s*numero\\s*>\\s*0\\s*\\)","Comprueba si es mayor que cero."],["Positivo","Incluye el mensaje Positivo."],["No positivo|No positivo","Incluye el mensaje alternativo."],["else","Incluye else."]]},
    {name:"Depura",type:"exercise",title:"Un solo signo lo cambia todo",body:"El código debería verificar si dos valores son iguales. Corrige el operador de comparación y el uso de la condición.",requirements:["Usa == para comparar.","La condición debe comparar a y b.","Muestra Igual y Diferente."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 5, b = 5;\n    if (a = b) {\n        cout << \"Igual\";\n    } else {\n        cout << \"Diferente\";\n    }\n    return 0;\n}',hint:"En una condición de igualdad necesitas `a == b`, no `a = b`.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int a = 5, b = 5;\n    if (a == b) {\n        cout << \"Igual\";\n    } else {\n        cout << \"Diferente\";\n    }\n    return 0;\n}',checks:[["if\\s*\\(\\s*a\\s*==\\s*b\\s*\\)","Compara a y b con ==."],["Igual","Muestra Igual."],["Diferente","Muestra Diferente."],["else","Incluye else."]]},
    {name:"Desafío",type:"exercise",title:"Descuento en una compra",body:"Lee el total de una compra. Si es de 1000 o más, aplica un descuento del 10 %. Muestra el total a pagar.",requirements:["Lee el total de la compra como double.","Usa if/else para el descuento.","Calcula el 90 % del total si aplica descuento.","Muestra el monto final."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    double total, pagar;\n    cin >> total;\n    // Aplica el descuento si corresponde\n    return 0;\n}',hint:"Si total >= 1000, calcula `pagar = total * 0.90;`; si no, `pagar = total;`.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    double total, pagar;\n    cin >> total;\n    if (total >= 1000) {\n        pagar = total * 0.90;\n    } else {\n        pagar = total;\n    }\n    cout << pagar << endl;\n    return 0;\n}',checks:[["cin\\s*>>\\s*total","Lee el total."],["if\\s*\\(\\s*total\\s*>=\\s*1000\\s*\\)","Verifica el monto mínimo."],["pagar\\s*=\\s*total\\s*\\*\\s*0\\.90","Aplica el descuento del 10 %."],["pagar\\s*=\\s*total\\s*;","Conserva el total cuando no hay descuento."],["cout\\s*<<\\s*pagar","Muestra el total final."]]}
  ]},
  {id:"cpp5",course:"cpp",title:"Ciclos y reto integrador",short:"Repite instrucciones",duration:"45–60 min",difficulty:"Intermedio inicial",summary:"Repite instrucciones con for y while y combina lo aprendido en un reto final.",concept:"Los ciclos permiten repetir instrucciones. `for` es útil cuando sabes cuántas repeticiones necesitas; `while` repite mientras una condición sea verdadera.",example:'for (int i = 1; i <= 5; i++) {\n    cout << i << endl;\n}',phases:[
    {name:"Aprende",type:"learn",title:"Repetir sin copiar y pegar",body:"Un ciclo evita escribir la misma instrucción muchas veces. En un for, la inicialización crea el contador, la condición decide cuándo continuar y el incremento actualiza el contador.",box:"Revisa la condición para evitar ciclos infinitos. En `i++`, la variable aumenta en uno cada vuelta.",items:[["for (int i=1; i<=5; i++)","Repite cinco veces, con i desde 1 hasta 5."],["while (condición)","Repite mientras la condición sea verdadera."],["i++","Aumenta el contador en uno."],["Bloque { }","Contiene las instrucciones que se repiten."]]},
    {name:"Construye",type:"exercise",title:"Cuenta del 1 al 10",body:"Escribe un ciclo for que muestre los números del 1 al 10, uno por línea.",requirements:["Usa un ciclo for.","Inicializa el contador en 1.","Usa una condición que llegue a 10.","Muestra el contador con cout."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Escribe el ciclo for\n    return 0;\n}',hint:"Una estructura posible es `for (int i = 1; i <= 10; i++) { cout << i << endl; }`.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 10; i++) {\n        cout << i << endl;\n    }\n    return 0;\n}',checks:[["for\\s*\\(","Usa for."],["int\\s+i\\s*=\\s*1","Inicia el contador en 1."],["i\\s*<=\\s*10","Llega hasta 10."],["i\\+\\+","Incrementa el contador."],["cout\\s*<<\\s*i","Muestra el contador."]]},
    {name:"Modifica",type:"exercise",title:"Cuenta hacia atrás",body:"Cambia el ciclo para mostrar del 5 al 1, en orden descendente.",requirements:["El contador empieza en 5.","La condición permite llegar a 1.","El contador disminuye en cada vuelta.","Muestra i."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 5; i++) {\n        cout << i << endl;\n    }\n    return 0;\n}',hint:"Empieza con i = 5, utiliza i >= 1 y reduce con i--.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    for (int i = 5; i >= 1; i--) {\n        cout << i << endl;\n    }\n    return 0;\n}',checks:[["int\\s+i\\s*=\\s*5","Empieza en 5."],["i\\s*>=\\s*1","Termina en 1."],["i\\s*--","Disminuye el contador."],["cout\\s*<<\\s*i","Muestra el contador."]]},
    {name:"Depura",type:"exercise",title:"El ciclo que nunca termina",body:"Corrige este ciclo para que muestre del 1 al 5 y termine correctamente.",requirements:["Corrige la condición del ciclo.","El contador debe aumentar.","El ciclo debe terminar en 5."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i >= 5; i--) {\n        cout << i << endl;\n    }\n    return 0;\n}',hint:"Si comienzas en 1 y quieres llegar a 5, usa i <= 5 y aumenta con i++.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    for (int i = 1; i <= 5; i++) {\n        cout << i << endl;\n    }\n    return 0;\n}',checks:[["int\\s+i\\s*=\\s*1","Empieza en 1."],["i\\s*<=\\s*5","La condición permite llegar a 5."],["i\\+\\+","Incrementa el contador."],["cout\\s*<<\\s*i","Muestra i."]]},
    {name:"Desafío",type:"exercise",title:"Suma los números del 1 al 10",body:"Crea un programa que utilice un ciclo para sumar todos los números del 1 al 10 y muestre el resultado final.",requirements:["Declara una variable suma e inicialízala en 0.","Usa un ciclo for del 1 al 10.","Acumula cada valor en suma.","Muestra el resultado después del ciclo."],starter:'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Resuelve el reto\n    return 0;\n}',hint:"Dentro del ciclo escribe `suma = suma + i;`. Inicializa suma en cero antes del for.",solution:'#include <iostream>\nusing namespace std;\n\nint main() {\n    int suma = 0;\n    for (int i = 1; i <= 10; i++) {\n        suma = suma + i;\n    }\n    cout << suma << endl;\n    return 0;\n}',checks:[["int\\s+suma\\s*=\\s*0","Inicializa suma en cero."],["for\\s*\\(","Usa un ciclo."],["i\\s*<=\\s*10","Llega hasta 10."],["suma\\s*=\\s*suma\\s*\\+\\s*i|suma\\s*\\+=\\s*i","Acumula cada número."],["cout\\s*<<\\s*suma","Muestra la suma final."]]}
  ]},
  {id:"sql1",course:"sql",title:"Tu primera tabla",short:"CREATE TABLE",duration:"35–45 min",difficulty:"Principiante",summary:"Comprende qué es una tabla y crea una estructura para almacenar información.",concept:"Una base de datos organiza información en tablas. Cada tabla tiene columnas (campos) y filas (registros). `CREATE TABLE` define la estructura de una tabla.",example:'create table estudiantes (\n    id_est int primary key,\n    nombre_est varchar(60),\n    edad_est int\n);',phases:[
    {name:"Aprende",type:"learn",title:"Una base de datos empieza con tablas",body:"Antes de guardar datos, defines qué información tendrá cada tabla. Cada columna tiene un nombre y un tipo de dato. `int` guarda enteros; `varchar(n)` guarda texto de hasta n caracteres.",box:"En este entrenamiento usamos SQL en minúsculas y tipos int/varchar para practicar el estilo que necesitas en tus ejercicios de PostgreSQL.",items:[["create table","Crea una nueva tabla."],["int","Tipo para números enteros."],["varchar(60)","Tipo para texto de hasta 60 caracteres."],["primary key","Identifica de forma única cada registro."]]},
    {name:"Construye",type:"exercise",title:"Crea la tabla estudiantes",body:"Escribe una instrucción SQL para crear estudiantes con id_est, nombre_est y edad_est.",requirements:["La tabla se llama estudiantes.","id_est es int y clave primaria.","nombre_est es varchar(60).","edad_est es int.","Cierra la instrucción con punto y coma."],starter:'-- Escribe tu CREATE TABLE aquí\n',hint:"Empieza con `create table estudiantes (` y coloca cada campo en una línea, separados por comas.",solution:'create table estudiantes (\n    id_est int primary key,\n    nombre_est varchar(60),\n    edad_est int\n);',checks:[["create\\s+table\\s+estudiantes","Crea la tabla estudiantes."],["id_est\\s+int\\s+primary\\s+key","Define id_est como clave primaria int."],["nombre_est\\s+varchar\\s*\\(\\s*60\\s*\\)","Define nombre_est como varchar(60)."],["edad_est\\s+int","Define edad_est como int."],[";\\s*$","Termina la instrucción con punto y coma."]]},
    {name:"Modifica",type:"exercise",title:"Añade un campo",body:"Amplía la tabla clientes para guardar un teléfono. La tabla debe incluir id_cli, nombre_cli y telefono_cli.",requirements:["Crea la tabla clientes.","id_cli debe ser int primary key.","nombre_cli debe ser varchar.","telefono_cli debe ser varchar.","Usa solo int y varchar como tipos."],starter:'create table clientes (\n    id_cli int primary key,\n    nombre_cli varchar(60)\n);',hint:"Añade una coma después de nombre_cli y antes del nuevo campo telefono_cli.",solution:'create table clientes (\n    id_cli int primary key,\n    nombre_cli varchar(60),\n    telefono_cli varchar(20)\n);',checks:[["create\\s+table\\s+clientes","Crea clientes."],["id_cli\\s+int\\s+primary\\s+key","Define la clave primaria."],["nombre_cli\\s+varchar","Incluye el nombre."],["telefono_cli\\s+varchar","Añade el teléfono."],[";\\s*$","Cierra la instrucción."]]},
    {name:"Depura",type:"exercise",title:"Repara la estructura SQL",body:"Este CREATE TABLE contiene errores de sintaxis. Corrige el tipo de dato y los separadores.",requirements:["Corrige varchar mal escrito.","Separa las columnas con comas.","Conserva una clave primaria.","Finaliza con punto y coma."],starter:'create table productos (\n    id_pro int primary key\n    nombre_pro varcar(50),\n    precio_pro int\n)',hint:"Entre columnas necesitas comas. El tipo correcto es varchar y la instrucción debe terminar con ;",solution:'create table productos (\n    id_pro int primary key,\n    nombre_pro varchar(50),\n    precio_pro int\n);',checks:[["create\\s+table\\s+productos","Mantiene la tabla productos."],["id_pro\\s+int\\s+primary\\s+key","Conserva la clave primaria."],["nombre_pro\\s+varchar\\s*\\(\\s*50\\s*\\)","Corrige varchar(50)."],["id_pro\\s+int\\s+primary\\s+key\\s*,","Separa la primera columna con coma."],[";\\s*$","Añade punto y coma final."]]},
    {name:"Desafío",type:"exercise",title:"Diseña una tabla de servicios",body:"Diseña una tabla servicios para un negocio. Debe guardar identificador, nombre del servicio, descripción y precio entero.",requirements:["La tabla se llama servicios.","Usa id_ser como clave primaria int.","Incluye nombre_ser y descripcion_ser como varchar.","Incluye precio_ser como int."],starter:'-- Diseña la tabla servicios\n',hint:"Piensa qué campos identifican al servicio y cuáles describen sus características.",solution:'create table servicios (\n    id_ser int primary key,\n    nombre_ser varchar(60),\n    descripcion_ser varchar(100),\n    precio_ser int\n);',checks:[["create\\s+table\\s+servicios","Crea la tabla servicios."],["id_ser\\s+int\\s+primary\\s+key","Incluye la clave primaria."],["nombre_ser\\s+varchar","Incluye el nombre."],["descripcion_ser\\s+varchar","Incluye la descripción."],["precio_ser\\s+int","Incluye el precio entero."]]}
  ]},
  {id:"sql2",course:"sql",title:"Inserta registros",short:"INSERT INTO",duration:"35–50 min",difficulty:"Principiante",summary:"Agrega filas a una tabla y distingue los datos de texto de los números.",concept:"`INSERT INTO` agrega registros. Especificar las columnas hace que la instrucción sea más clara. Los textos se escriben entre comillas simples; los números normalmente van sin comillas.",example:"insert into estudiantes (id_est, nombre_est, edad_est)\nvalues (1, 'Ana', 16);",phases:[
    {name:"Aprende",type:"learn",title:"Guarda información en una tabla",body:"Después de crear una tabla, puedes agregar registros. La lista de columnas debe coincidir en orden y cantidad con los valores que colocas en `values`.",box:"SQL usa comillas simples para texto: 'Ana'. Para un valor entero, como 16, no necesitas comillas.",items:[["insert into tabla","Indica dónde guardar el registro."],["(columna1, columna2)","Nombra las columnas que recibirán valores."],["values (1, 'Ana')","Proporciona valores en el mismo orden."],[";","Finaliza la instrucción SQL."]]},
    {name:"Construye",type:"exercise",title:"Agrega dos estudiantes",body:"Escribe dos instrucciones INSERT para agregar a Ana (16 años) y Luis (17 años) con identificadores 1 y 2.",requirements:["Usa insert into estudiantes.","Especifica id_est, nombre_est y edad_est.","Inserta a Ana y a Luis.","Usa comillas simples para los nombres."],starter:'-- Inserta los dos estudiantes\n',hint:"Necesitas dos instrucciones insert. Cada una termina en ; y cada nombre va entre comillas simples.",solution:"insert into estudiantes (id_est, nombre_est, edad_est) values (1, 'Ana', 16);\ninsert into estudiantes (id_est, nombre_est, edad_est) values (2, 'Luis', 17);",checks:[["insert\\s+into\\s+estudiantes","Inserta en estudiantes."],["'Ana'","Incluye a Ana como texto."],["'Luis'","Incluye a Luis como texto."],["values\\s*\\(\\s*1\\s*,","Incluye el primer registro."],["values\\s*\\(\\s*2\\s*,","Incluye el segundo registro."]]},
    {name:"Modifica",type:"exercise",title:"Inserta un servicio",body:"Escribe un INSERT para guardar un servicio llamado Corte de pelo con id 1, descripción Corte clásico y precio 150.",requirements:["Inserta en servicios.","Incluye id_ser, nombre_ser, descripcion_ser y precio_ser.","Usa texto entre comillas simples.","El precio debe ser 150."],starter:"insert into servicios (id_ser, nombre_ser)\nvalues (1, 'Servicio');",hint:"Incluye los cuatro nombres de columna y cuatro valores en el mismo orden.",solution:"insert into servicios (id_ser, nombre_ser, descripcion_ser, precio_ser)\nvalues (1, 'Corte de pelo', 'Corte clasico', 150);",checks:[["insert\\s+into\\s+servicios","Inserta en servicios."],["id_ser","Incluye id_ser."],["nombre_ser","Incluye nombre_ser."],["descripcion_ser","Incluye descripcion_ser."],["precio_ser","Incluye precio_ser."],["150","Usa el precio indicado."]]},
    {name:"Depura",type:"exercise",title:"Comillas y columnas",body:"Corrige el INSERT: las columnas y valores deben coincidir y el texto necesita comillas simples.",requirements:["Corrige las comillas de Ana.","Asegura que haya tres columnas y tres valores.","Usa la palabra values.","Termina con punto y coma."],starter:'insert into estudiantes (id_est, nombre_est, edad_est)\nvalues (1, Ana, 16)',hint:"Escribe el texto como 'Ana' y añade el punto y coma final.",solution:"insert into estudiantes (id_est, nombre_est, edad_est)\nvalues (1, 'Ana', 16);",checks:[["insert\\s+into\\s+estudiantes","Inserta en la tabla correcta."],["values\\s*\\(\\s*1\\s*,\\s*'Ana'\\s*,\\s*16\\s*\\)","Los valores coinciden y el texto usa comillas."],[";\\s*$","Termina con punto y coma."]]},
    {name:"Desafío",type:"exercise",title:"Carga inicial de clientes",body:"Escribe dos INSERT para registrar a Marta y José en la tabla clientes. Usa id_cli 1 y 2, nombres y teléfonos.",requirements:["Inserta dos registros en clientes.","Incluye id_cli, nombre_cli y telefono_cli.","Usa comillas simples para nombres y teléfonos.","Los identificadores son 1 y 2."],starter:'-- Inserta dos clientes\n',hint:"El teléfono se guarda como varchar, así que colócalo entre comillas simples.",solution:"insert into clientes (id_cli, nombre_cli, telefono_cli) values (1, 'Marta', '99990001');\ninsert into clientes (id_cli, nombre_cli, telefono_cli) values (2, 'Jose', '99990002');",checks:[["insert\\s+into\\s+clientes","Inserta en clientes."],["'Marta'","Incluye a Marta."],["'Jose'| 'José'|'José'","Incluye a José."],["values\\s*\\(\\s*1\\s*,","Usa el identificador 1."],["values\\s*\\(\\s*2\\s*,","Usa el identificador 2."]]}
  ]},
  {id:"sql3",course:"sql",title:"Consulta con SELECT",short:"Filtra información",duration:"40–55 min",difficulty:"Principiante",summary:"Consulta todos los registros, selecciona columnas y filtra resultados.",concept:"`SELECT` recupera información. `*` significa todas las columnas. `WHERE` filtra filas que cumplen una condición. Puedes ordenar resultados con `ORDER BY`.",example:"select nombre_est, edad_est\nfrom estudiantes\nwhere edad_est >= 17\norder by nombre_est;",phases:[
    {name:"Aprende",type:"learn",title:"Pregúntale a tu base de datos",body:"Una consulta SELECT no cambia los datos: solo solicita que se muestren. Puedes elegir columnas, indicar la tabla y filtrar filas con WHERE.",box:"Lee la consulta como una frase: selecciona estas columnas, desde esta tabla, donde se cumpla esta condición.",items:[["select *","Selecciona todas las columnas."],["from estudiantes","Indica de qué tabla obtener datos."],["where edad_est >= 17","Filtra estudiantes de 17 años o más."],["order by nombre_est","Ordena por nombre."]]},
    {name:"Construye",type:"exercise",title:"Consulta estudiantes",body:"Escribe una consulta que muestre todos los datos de la tabla estudiantes.",requirements:["Usa select.","Selecciona todas las columnas con *.","Consulta desde estudiantes.","Termina con punto y coma."],starter:'-- Consulta todos los estudiantes\n',hint:"La consulta mínima tiene dos partes: `select *` y `from estudiantes;`",solution:'select * from estudiantes;',checks:[["select\\s+\\*","Selecciona todas las columnas."],["from\\s+estudiantes","Consulta estudiantes."],[";\\s*$","Termina con punto y coma."]]},
    {name:"Modifica",type:"exercise",title:"Filtra por edad",body:"Modifica la consulta para mostrar solo nombre_est y edad_est de los estudiantes que tengan 17 años o más.",requirements:["Selecciona solo nombre_est y edad_est.","Consulta desde estudiantes.","Usa WHERE edad_est >= 17.","Finaliza con punto y coma."],starter:'select * from estudiantes;',hint:"Después de `from estudiantes` agrega `where edad_est >= 17` y cambia las columnas seleccionadas.",solution:'select nombre_est, edad_est from estudiantes where edad_est >= 17;',checks:[["select\\s+nombre_est\\s*,\\s*edad_est","Selecciona las dos columnas solicitadas."],["from\\s+estudiantes","Consulta estudiantes."],["where\\s+edad_est\\s*>=\\s*17","Filtra por edad."],[";\\s*$","Termina la consulta."]]},
    {name:"Depura",type:"exercise",title:"Ordena y filtra",body:"Corrige la consulta para que muestre clientes cuyo id_cli sea mayor que 1 y los ordene por nombre_cli.",requirements:["Usa select y from clientes.","Filtra con where id_cli > 1.","Ordena con order by nombre_cli.","Usa la sintaxis correcta."],starter:'select * clientes\nwhere id_cli => 1\norder nombre_cli;',hint:"Falta FROM. El operador correcto es >, y la cláusula de orden es order by.",solution:'select * from clientes where id_cli > 1 order by nombre_cli;',checks:[["select\\s+\\*\\s+from\\s+clientes","Usa FROM clientes."],["where\\s+id_cli\\s*>\\s*1","Corrige el filtro."],["order\\s+by\\s+nombre_cli","Ordena por nombre."],[";\\s*$","Finaliza la consulta."]]},
    {name:"Desafío",type:"exercise",title:"Busca servicios económicos",body:"Consulta nombre_ser y precio_ser de servicios cuyo precio sea menor o igual a 200, ordenados por precio.",requirements:["Selecciona nombre_ser y precio_ser.","Consulta desde servicios.","Filtra con precio_ser <= 200.","Ordena por precio_ser."],starter:'-- Escribe la consulta\n',hint:"Combina SELECT, FROM, WHERE y ORDER BY en ese orden.",solution:'select nombre_ser, precio_ser from servicios where precio_ser <= 200 order by precio_ser;',checks:[["select\\s+nombre_ser\\s*,\\s*precio_ser","Selecciona las columnas correctas."],["from\\s+servicios","Consulta servicios."],["where\\s+precio_ser\\s*<=\\s*200","Filtra por precio."],["order\\s+by\\s+precio_ser","Ordena por precio."]]}
  ]},
  {id:"sql4",course:"sql",title:"Actualizar y eliminar",short:"UPDATE y DELETE",duration:"40–55 min",difficulty:"Principiante+",summary:"Aprende a modificar registros y a eliminar filas con cuidado.",concept:"`UPDATE` cambia valores existentes; `DELETE` elimina filas. Ambas instrucciones suelen necesitar `WHERE`. Sin WHERE, puedes modificar o eliminar todos los registros de una tabla.",example:"update clientes\nset telefono_cli = '99991111'\nwhere id_cli = 1;\n\ndelete from clientes\nwhere id_cli = 2;",phases:[
    {name:"Aprende",type:"learn",title:"Modificar datos con cuidado",body:"UPDATE indica la tabla, SET especifica el nuevo valor y WHERE selecciona qué fila modificar. DELETE FROM elimina los registros que cumplan la condición.",box:"Antes de ejecutar UPDATE o DELETE en una base real, comprueba la condición WHERE. Omitirla puede afectar todas las filas.",items:[["update clientes","Indica qué tabla modificar."],["set telefono_cli = '...'","Asigna el nuevo valor."],["where id_cli = 1","Limita el cambio a un registro."],["delete from clientes","Elimina filas que coincidan con WHERE."]]},
    {name:"Construye",type:"exercise",title:"Actualiza un teléfono",body:"Escribe una consulta que cambie el teléfono del cliente con id_cli 1 a 99991111.",requirements:["Usa update clientes.","Asigna el nuevo valor con set.","Filtra por id_cli = 1.","Termina con punto y coma."],starter:'-- Actualiza el teléfono del cliente 1\n',hint:"La estructura es `update clientes set telefono_cli = '99991111' where id_cli = 1;`",solution:"update clientes set telefono_cli = '99991111' where id_cli = 1;",checks:[["update\\s+clientes","Modifica clientes."],["set\\s+telefono_cli\\s*=","Actualiza el teléfono."],["where\\s+id_cli\\s*=\\s*1","Limita el cambio al cliente 1."],[";\\s*$","Finaliza la instrucción."]]},
    {name:"Modifica",type:"exercise",title:"Elimina un registro específico",body:"Escribe un DELETE para eliminar el servicio cuyo id_ser sea 3. La consulta debe incluir una condición.",requirements:["Usa delete from servicios.","Filtra con where id_ser = 3.","No omitas WHERE.","Termina con punto y coma."],starter:'delete from servicios;',hint:"Añade `where id_ser = 3` para que no se eliminen todos los servicios.",solution:'delete from servicios where id_ser = 3;',checks:[["delete\\s+from\\s+servicios","Elimina desde servicios."],["where\\s+id_ser\\s*=\\s*3","Limita la eliminación al id 3."],[";\\s*$","Finaliza la instrucción."]]},
    {name:"Depura",type:"exercise",title:"Evita actualizar toda la tabla",body:"Repara la consulta para que solo cambie el precio del servicio con id_ser 2 a 180.",requirements:["Usa update servicios.","Usa set precio_ser = 180.","Incluye where id_ser = 2.","No elimines la condición."],starter:'update servicios\nprecio_ser = 180\nwhere id_ser 2;',hint:"Entre update y set falta la palabra SET; en WHERE necesitas el operador =.",solution:'update servicios set precio_ser = 180 where id_ser = 2;',checks:[["update\\s+servicios","Actualiza servicios."],["set\\s+precio_ser\\s*=\\s*180","Establece el precio."],["where\\s+id_ser\\s*=\\s*2","Filtra por el identificador correcto."],[";\\s*$","Finaliza la consulta."]]},
    {name:"Desafío",type:"exercise",title:"Actualiza y elimina con seguridad",body:"Escribe dos instrucciones: cambia el nombre del cliente id 2 a José y elimina el cliente id 5.",requirements:["Incluye una instrucción UPDATE.","Incluye una instrucción DELETE.","Ambas instrucciones tienen WHERE.","Usa nombres de tabla y campos correctos."],starter:'-- Actualiza un cliente y elimina otro\n',hint:"Recuerda que cada instrucción necesita su propia cláusula WHERE y su punto y coma.",solution:"update clientes set nombre_cli = 'Jose' where id_cli = 2;\ndelete from clientes where id_cli = 5;",checks:[["update\\s+clientes","Incluye UPDATE."],["set\\s+nombre_cli\\s*=","Cambia el nombre."],["where\\s+id_cli\\s*=\\s*2","Actualiza el cliente 2."],["delete\\s+from\\s+clientes","Incluye DELETE."],["where\\s+id_cli\\s*=\\s*5","Elimina solo el cliente 5."]]}
  ]},
  {id:"sql5",course:"sql",title:"Relaciones entre tablas",short:"Claves y JOIN",duration:"45–60 min",difficulty:"Intermedio inicial",summary:"Relaciona tablas mediante claves foráneas y consulta datos relacionados.",concept:"Una clave primaria identifica cada fila. Una clave foránea referencia la clave primaria de otra tabla para relacionar información sin duplicarla.",example:"create table atenciones (\n    id_at int primary key,\n    id_cli int,\n    id_ser int,\n    foreign key (id_cli) references clientes(id_cli),\n    foreign key (id_ser) references servicios(id_ser)\n);",phases:[
    {name:"Aprende",type:"learn",title:"Las tablas pueden conectarse",body:"Una base relacional guarda cada tipo de entidad en su tabla y usa claves para conectarlas. En una atención, por ejemplo, guardas el identificador del cliente y el del servicio.",box:"Una foreign key debe apuntar a una columna que identifica registros en otra tabla. En una consulta JOIN, relacionas filas usando la condición ON.",items:[["primary key","Identifica de forma única una fila."],["foreign key","Referencia una clave de otra tabla."],["references clientes(id_cli)","Indica qué columna se referencia."],["join ... on","Combina filas de tablas relacionadas."]]},
    {name:"Construye",type:"exercise",title:"Crea la tabla atenciones",body:"Crea una tabla atenciones con id_at como clave primaria, id_cli e id_ser como enteros, y ambas claves foráneas.",requirements:["Crea la tabla atenciones.","id_at es int primary key.","id_cli referencia clientes(id_cli).","id_ser referencia servicios(id_ser)."],starter:'create table atenciones (\n    -- Define los campos y las relaciones\n);',hint:"Primero declara los tres campos. Después añade `foreign key (id_cli) references clientes(id_cli)` y la relación con servicios.",solution:'create table atenciones (\n    id_at int primary key,\n    id_cli int,\n    id_ser int,\n    foreign key (id_cli) references clientes(id_cli),\n    foreign key (id_ser) references servicios(id_ser)\n);',checks:[["create\\s+table\\s+atenciones","Crea atenciones."],["id_at\\s+int\\s+primary\\s+key","Define la clave primaria."],["foreign\\s+key\\s*\\(\\s*id_cli\\s*\\)\\s+references\\s+clientes\\s*\\(\\s*id_cli\\s*\\)","Relaciona atenciones con clientes."],["foreign\\s+key\\s*\\(\\s*id_ser\\s*\\)\\s+references\\s+servicios\\s*\\(\\s*id_ser\\s*\\)","Relaciona atenciones con servicios."]]},
    {name:"Modifica",type:"exercise",title:"Consulta atenciones relacionadas",body:"Escribe una consulta que combine atenciones con clientes usando id_cli como campo de relación.",requirements:["Selecciona datos de atenciones y clientes.","Usa JOIN clientes.","Relaciona atenciones.id_cli con clientes.id_cli mediante ON."],starter:'select *\nfrom atenciones;',hint:"Después de `from atenciones`, añade `join clientes on atenciones.id_cli = clientes.id_cli`.",solution:'select * from atenciones join clientes on atenciones.id_cli = clientes.id_cli;',checks:[["select\\s+\\*","Selecciona datos."],["from\\s+atenciones","Parte de atenciones."],["join\\s+clientes","Une la tabla clientes."],["on\\s+atenciones\\.id_cli\\s*=\\s*clientes\\.id_cli","Usa la condición de relación correcta."]]},
    {name:"Depura",type:"exercise",title:"Corrige las claves foráneas",body:"Corrige la sintaxis de esta tabla: las palabras FOREIGN KEY y REFERENCES están incompletas.",requirements:["Usa foreign key (id_cli).","Referencia clientes(id_cli).","Mantén id_at como clave primaria."],starter:'create table atenciones (\n    id_at int primary key,\n    id_cli int,\n    foreing key (id_cli) referens clientes(id_cli)\n);',hint:"La sintaxis exacta es `foreign key (id_cli) references clientes(id_cli)`.",solution:'create table atenciones (\n    id_at int primary key,\n    id_cli int,\n    foreign key (id_cli) references clientes(id_cli)\n);',checks:[["id_at\\s+int\\s+primary\\s+key","Conserva la clave primaria."],["foreign\\s+key\\s*\\(\\s*id_cli\\s*\\)","Corrige FOREIGN KEY."],["references\\s+clientes\\s*\\(\\s*id_cli\\s*\\)","Corrige REFERENCES."],[";\\s*$","Finaliza la instrucción."]]},
    {name:"Desafío",type:"exercise",title:"Reporte de atención",body:"Diseña una consulta que muestre id_at, nombre_cli y nombre_ser combinando atenciones, clientes y servicios.",requirements:["Selecciona id_at, nombre_cli y nombre_ser.","Une atenciones con clientes por id_cli.","Une atenciones con servicios por id_ser.","Usa condiciones ON correctas."],starter:'-- Escribe el reporte de atenciones\n',hint:"Puedes encadenar dos JOIN: uno para clientes y otro para servicios.",solution:'select atenciones.id_at, clientes.nombre_cli, servicios.nombre_ser\nfrom atenciones\njoin clientes on atenciones.id_cli = clientes.id_cli\njoin servicios on atenciones.id_ser = servicios.id_ser;',checks:[["select\\s+atenciones\\.id_at","Selecciona id_at."],["clientes\\.nombre_cli","Selecciona el nombre del cliente."],["servicios\\.nombre_ser","Selecciona el nombre del servicio."],["join\\s+clientes\\s+on\\s+atenciones\\.id_cli\\s*=\\s*clientes\\.id_cli","Une clientes correctamente."],["join\\s+servicios\\s+on\\s+atenciones\\.id_ser\\s*=\\s*servicios\\.id_ser","Une servicios correctamente."]]}
  ]}
];

// Módulo 6 de cada ruta: cierre práctico con contenido alineado a PostgreSQL y C++.
const capstone = (course, data) => ({
  id: data.id, course, title: data.title, short: data.short, duration: "45–60 min",
  difficulty: "Intermedio inicial", summary: data.summary, concept: data.concept,
  example: data.example,
  phases: [
    {name:"Aprende",type:"learn",title:data.learnTitle,body:data.learnBody,box:data.learnBox,items:data.items},
    ...data.exercises.map((e,i)=>({name:["Construye","Modifica","Depura","Desafío"][i],type:"exercise",...e}))
  ]
});
lessons.push(capstone("cpp", {
  id:"cpp6",title:"Funciones y reto integrador",short:"Funciones y arreglos",summary:"Organiza un programa en funciones y procesa una lista de valores para resolver un reto completo.",
  concept:"Una función agrupa instrucciones con un nombre. Los parámetros reciben datos; return puede devolver un resultado. Un arreglo guarda varios valores del mismo tipo.",
  example:'#include <iostream>\nusing namespace std;\n\nint sumar(int a, int b) { return a + b; }\n\nint main() {\n    int valores[3] = {4, 7, 2};\n    cout << sumar(valores[0], valores[1]);\n    return 0;\n}',
  learnTitle:"Divide el problema en partes",learnBody:"Una función permite nombrar una tarea y reutilizarla. Declara el tipo que devuelve, sus parámetros y el cuerpo entre llaves. Un arreglo como `int notas[3]` guarda varios enteros bajo un mismo nombre.",
  learnBox:"Resuelve primero una tarea pequeña, como calcular un promedio, y luego llámala desde `main()`. Los índices de un arreglo comienzan en 0.",
  items:[["int sumar(int a, int b)","Define una función que recibe dos enteros."],["return a + b;","Devuelve el resultado al lugar que llamó la función."],["int notas[3]","Reserva espacio para tres valores enteros."],["notas[0]","Accede al primer elemento del arreglo."]],
  exercises:[
    {title:"Crea una función de suma",body:"Escribe una función sumar que reciba dos enteros y devuelva su suma. Llámala desde main y muestra el resultado.",requirements:["Define int sumar con dos parámetros int.","Devuelve a + b.","Llama a sumar desde main.","Muestra el resultado con cout."],starter:'#include <iostream>\nusing namespace std;\n\n// Define sumar aquí\n\nint main() {\n    // Llama y muestra el resultado\n    return 0;\n}',hint:"La firma puede ser `int sumar(int a, int b)`. Dentro usa `return a + b;`.",solution:'#include <iostream>\nusing namespace std;\nint sumar(int a, int b) { return a + b; }\nint main() { cout << sumar(3, 4); return 0; }',checks:[["int\\s+sumar\\s*\\(\\s*int\\s+\\w+\\s*,\\s*int\\s+\\w+\\s*\\)","Define sumar con dos parámetros enteros."],["return\\s+\\w+\\s*\\+\\s*\\w+\\s*;","Devuelve la suma."],["sumar\\s*\\(","Llama a la función."],["cout\\s*<<","Muestra un resultado."]] },
    {title:"Calcula un promedio",body:"Completa una función que reciba tres calificaciones decimales y devuelva el promedio. Muestra el valor desde main.",requirements:["Define una función double promedio.","Recibe tres valores double.","Suma y divide entre 3.","Muestra una llamada a promedio."],starter:'#include <iostream>\nusing namespace std;\n\n// Define promedio\n\nint main() {\n    cout << promedio(80, 90, 100);\n    return 0;\n}',hint:"Usa `(a + b + c) / 3.0` para conservar decimales.",solution:'double promedio(double a, double b, double c) { return (a + b + c) / 3.0; }\nint main() { std::cout << promedio(80, 90, 100); return 0; }',checks:[["double\\s+promedio\\s*\\(\\s*double\\s+\\w+\\s*,\\s*double\\s+\\w+\\s*,\\s*double\\s+\\w+\\s*\\)","Define promedio con tres valores double."],["return\\s+\\([^;]*\\+[^;]*\\+[^;]*\\)\\s*\\/\\s*3(?:\\.0)?\\s*;","Suma los tres valores y divide entre 3."],["cout\\s*<<\\s*promedio\\s*\\(|std::cout\\s*<<\\s*promedio\\s*\\(","Muestra el resultado de promedio."]] },
    {title:"Corrige los límites del arreglo",body:"Corrige el ciclo para recorrer los cuatro elementos del arreglo sin salir de sus límites y calcular su suma.",requirements:["Conserva un arreglo de cuatro enteros.","El ciclo inicia en 0 y llega hasta el índice 3.","Acumula cada valor en suma.","Muestra suma."],starter:'int valores[4] = {2, 4, 6, 8};\nint suma = 0;\nfor (int i = 0; i <= 4; i++) {\n    suma = valores[i];\n}',hint:"Con cuatro elementos, los índices válidos van de 0 a 3. El acumulador debe sumar, no reemplazar su valor.",solution:'int valores[4] = {2, 4, 6, 8};\nint suma = 0;\nfor (int i = 0; i < 4; i++) { suma += valores[i]; }\ncout << suma;',checks:[["int\\s+valores\\s*\\[\\s*4\\s*\\]","Conserva cuatro elementos."],["for\\s*\\(\\s*int\\s+i\\s*=\\s*0\\s*;\\s*i\\s*<\\s*4","Recorre desde 0 sin superar el límite."],["suma\\s*\\+=\\s*valores\\s*\\[\\s*i\\s*\\]","Acumula cada elemento."],["cout\\s*<<\\s*suma","Muestra la suma."]] },
    {title:"Reto: resumen de calificaciones",body:"Crea un arreglo con tres notas, calcula el promedio mediante una función y muestra el resultado.",requirements:["Declara un arreglo con tres notas.","Define una función para calcular el promedio.","Llama la función con los valores del arreglo.","Muestra el resultado."],starter:'#include <iostream>\nusing namespace std;\n\n// Define una función para el promedio\n\nint main() {\n    // Declara notas y muestra el promedio\n    return 0;\n}',hint:"Puedes pasar `notas[0]`, `notas[1]` y `notas[2]` a una función promedio de tres parámetros.",solution:'double promedio(double a,double b,double c){return (a+b+c)/3.0;}\nint main(){int notas[3]={80,90,100};cout << promedio(notas[0],notas[1],notas[2]);}',checks:[["int\\s+notas\\s*\\[\\s*3\\s*\\]","Declara tres notas."],["double\\s+promedio\\s*\\(","Define una función que devuelve double."],["promedio\\s*\\(\\s*notas\\s*\\[\\s*0\\s*\\]\\s*,\\s*notas\\s*\\[\\s*1\\s*\\]\\s*,\\s*notas\\s*\\[\\s*2\\s*\\]","Usa los tres valores del arreglo."],["cout\\s*<<","Muestra el promedio."]] }
  ]
}));
lessons.push(capstone("sql", {
  id:"sql6",title:"Agregaciones y proyecto pulpería",short:"GROUP BY y consultas",summary:"Resume datos con funciones de agregación y diseña consultas para un pequeño sistema de ventas en PostgreSQL.",
  concept:"Las funciones agregadas calculan un resumen sobre varias filas. GROUP BY forma grupos; HAVING filtra esos grupos después de agregarlos. JOIN relaciona las tablas necesarias para responder preguntas del negocio.",
  example:"select id_producto, sum(cantidad) as unidades\nfrom detalle_venta\ngroup by id_producto\nhaving sum(cantidad) > 5;",
  learnTitle:"Resume información con SQL",learnBody:"COUNT cuenta filas, SUM suma valores y AVG calcula un promedio. GROUP BY produce una fila por grupo. WHERE filtra registros antes del resumen; HAVING filtra los resultados agrupados.",
  learnBox:"En PostgreSQL, cada columna seleccionada que no está dentro de una agregación debe incluirse en GROUP BY.",
  items:[["count(*)","Cuenta las filas de un grupo."],["sum(cantidad)","Suma los valores de una columna numérica."],["group by categoria","Produce un resultado por categoría."],["having count(*) > 2","Filtra grupos usando una agregación."]],
  exercises:[
    {title:"Cuenta las ventas",body:"Consulta cuántas ventas hay en la tabla ventas y nombra el resultado total_ventas.",requirements:["Usa SELECT count(*).","Consulta desde ventas.","Usa el alias total_ventas.","Termina con punto y coma."],starter:"-- Cuenta todas las ventas\n",hint:"La forma es `select count(*) as total_ventas from ventas;`.",solution:"select count(*) as total_ventas from ventas;",checks:[["select\\s+count\\s*\\(\\s*\\*\\s*\\)\\s+as\\s+total_ventas","Cuenta y asigna el alias indicado."],["from\\s+ventas","Consulta ventas."],[";\\s*$","Termina con punto y coma."]] },
    {title:"Suma ventas por producto",body:"Calcula la cantidad total vendida de cada producto usando detalle_venta y agrupa por id_producto.",requirements:["Usa sum(cantidad).","Consulta detalle_venta.","Agrupa por id_producto.","Asigna el alias unidades."],starter:"select id_producto from detalle_venta;",hint:"La cláusula GROUP BY va después de FROM.",solution:"select id_producto, sum(cantidad) as unidades from detalle_venta group by id_producto;",checks:[["sum\\s*\\(\\s*cantidad\\s*\\)\\s+as\\s+unidades","Suma cantidades con el alias solicitado."],["from\\s+detalle_venta","Consulta el detalle."],["group\\s+by\\s+id_producto","Agrupa por producto."]] },
    {title:"Repara WHERE y HAVING",body:"Corrige la consulta para resumir unidades por producto y conservar solo grupos con más de cinco unidades.",requirements:["Selecciona id_producto y sum(cantidad).","Agrupa por id_producto.","Filtra grupos con HAVING sum(cantidad) > 5.","Usa la sintaxis correcta."],starter:"select id_producto, sum(cantidad)\nfrom detalle_venta\nwhere sum(cantidad) > 5\ngroup by id_producto;",hint:"WHERE no filtra resultados agregados. Cambia esa cláusula por HAVING y colócala después de GROUP BY.",solution:"select id_producto, sum(cantidad) from detalle_venta group by id_producto having sum(cantidad) > 5;",checks:[["select\\s+id_producto\\s*,\\s*sum\\s*\\(\\s*cantidad\\s*\\)","Selecciona el producto y su suma."],["group\\s+by\\s+id_producto","Agrupa por producto."],["having\\s+sum\\s*\\(\\s*cantidad\\s*\\)\\s*>\\s*5","Filtra los grupos con HAVING."]] },
    {title:"Proyecto: reporte de pulpería",body:"Escribe una consulta que una ventas con clientes, muestre el nombre del cliente y cuente las ventas por persona.",requirements:["Une ventas con clientes.","La relación es ventas.id_cliente = clientes.id_cliente.","Cuenta las ventas.","Agrupa por id_cliente y nombre."],starter:"-- Reporte de ventas por cliente\n",hint:"Usa JOIN ... ON, luego GROUP BY para las dos columnas del cliente.",solution:"select clientes.nombre, count(*) as total_ventas from ventas join clientes on ventas.id_cliente = clientes.id_cliente group by clientes.id_cliente, clientes.nombre;",checks:[["join\\s+clientes\\s+on\\s+ventas\\.id_cliente\\s*=\\s*clientes\\.id_cliente","Une clientes usando la clave indicada."],["clientes\\.nombre","Muestra el nombre del cliente."],["count\\s*\\(\\s*\\*\\s*\\)","Cuenta las ventas."],["group\\s+by\\s+clientes\\.id_cliente\\s*,\\s*clientes\\.nombre","Agrupa por identificador y nombre."]] }
  ]
}));

// Rutas ampliadas: una sesión por concepto, con tareas para crear, modificar,
// depurar y resolver desde cero. Los validadores pertenecen a cada ejercicio.
const focusedLesson = d => ({
  id:d.id, course:d.course, title:d.title, short:d.short, duration:"40–60 min",
  difficulty:d.difficulty||"Principiante", summary:d.summary, concept:d.concept,
  example:d.example,
  phases:[
    {name:"Aprende",type:"learn",title:d.learnTitle,body:d.learnBody,box:d.box,items:d.items},
    ...d.tasks.map((task,i)=>({name:["Construye","Modifica","Depura","Desafío"][i],type:"exercise",...task}))
  ]
});
const addFocused=(course,d)=>lessons.push(focusedLesson({course,...d}));

addFocused("cpp",{
 id:"cpp7",title:"Bibliotecas y directivas #include",short:"Elegir bibliotecas",summary:"Aprende a identificar qué biblioteca necesitas y cómo incluirla antes de usar sus herramientas.",
 concept:"Una biblioteca reúne herramientas disponibles para el programa. La directiva #include incorpora su declaración; por ejemplo, iostream ofrece cout y cin, y string permite usar el tipo string.",
 example:'#include <iostream>\n#include <string>\nusing namespace std;\nint main() { string nombre; cin >> nombre; cout << nombre; return 0; }',
 learnTitle:"¿Qué biblioteca necesito?",learnBody:"Lee los elementos que quieres usar antes de programar. Para entrada y salida en consola, incluye `<iostream>`. Para trabajar con `string`, incluye `<string>`. La directiva va antes de `main()`.",box:"Una biblioteca incluida hace disponibles sus declaraciones; no reemplaza la lógica que debes escribir.",
 items:[["#include <iostream>","Declara cout, cin y otros elementos de entrada/salida."],["#include <string>","Permite usar el tipo std::string."],["Antes de main()","Las directivas de inclusión se escriben al inicio del archivo."],["Solo lo necesario","Incluye las bibliotecas que necesita el programa."]],
 tasks:[
 {title:"Incluye entrada y salida",body:"Prepara un programa de consola que lea y muestre un número entero.",requirements:["Incluye iostream.","Lee el entero con cin.","Muestra el valor con cout."],starter:"// Agrega la biblioteca y el código\nint main() { int edad; return 0; }",hint:"Escribe `#include <iostream>` antes de `main()`.",solution:'#include <iostream>\nint main() { int edad; std::cin >> edad; std::cout << edad; return 0; }',checks:[["#include\\s*<iostream>","Incluye iostream."],["cin\\s*>>\\s*edad|std::cin\\s*>>\\s*edad","Lee edad."],["cout\\s*<<\\s*edad|std::cout\\s*<<\\s*edad","Muestra edad."]] },
 {title:"Añade soporte para texto",body:"Modifica el programa para guardar un nombre en una variable string y mostrarlo.",requirements:["Incluye iostream y string.","Declara una variable string.","Muestra el nombre."],starter:'#include <iostream>\nint main() { std::string nombre = "Ana"; return 0; }',hint:"Agrega `#include <string>` o conserva el prefijo `std::` en el tipo.",solution:'#include <iostream>\n#include <string>\nint main() { std::string nombre = "Ana"; std::cout << nombre; return 0; }',checks:[["#include\\s*<iostream>","Conserva iostream."],["#include\\s*<string>|std::string","Incluye o califica el tipo string."],["cout\\s*<<\\s*nombre|std::cout\\s*<<\\s*nombre","Muestra el nombre."]] },
 {title:"Detecta la biblioteca faltante",body:"Repara el programa que utiliza cout y cin, pero no incluye su biblioteca.",requirements:["Añade iostream.","Mantén la lectura con cin.","Mantén la salida con cout."],starter:'int main() { int n; cin >> n; cout << n; return 0; }',hint:"La biblioteca que declara cin y cout es iostream.",solution:'#include <iostream>\nint main() { int n; std::cin >> n; std::cout << n; return 0; }',checks:[["#include\\s*<iostream>","Añade iostream."],["cin\\s*>>\\s*n|std::cin\\s*>>\\s*n","Conserva la entrada."],["cout\\s*<<\\s*n|std::cout\\s*<<\\s*n","Conserva la salida."]] },
 {title:"Programa desde cero: ficha",body:"Escribe un programa pequeño que lea un nombre y lo muestre. Incluye explícitamente la biblioteca necesaria.",requirements:["Incluye iostream y string.","Declara nombre como string.","Lee nombre y lo imprime."],starter:"// Escribe el programa completo\n",hint:"Orden sugerido: includes, main, variable, cin, cout y return.",solution:'#include <iostream>\n#include <string>\nint main() { std::string nombre; std::cin >> nombre; std::cout << nombre; return 0; }',checks:[["#include\\s*<iostream>","Incluye iostream."],["#include\\s*<string>|std::string","Soporta string."],["cin\\s*>>\\s*nombre|std::cin\\s*>>\\s*nombre","Lee el nombre."],["cout\\s*<<\\s*nombre|std::cout\\s*<<\\s*nombre","Muestra el nombre."]] }
 ]
});

