function makeLanguageCourse(lang){
 const s=lang.syntax, base=`lang-${lang.id}-`;
 const phase=(title,body,box,items,example,tasks)=>({
  id:base+({"Sintaxis y salida":"1","Decisiones y flujo":"2","Funciones y colecciones":"3"}[title]),course:lang.id,title,short:({"Sintaxis y salida":"Primeros pasos","Decisiones y flujo":"Condiciones","Funciones y colecciones":"Funciones y listas"}[title]),duration:"35–50 min",difficulty:"Principiante",summary:body,concept:box,example,
  phases:[{name:"Aprende",type:"learn",title,body,box,items},...tasks.map((t,i)=>({name:["Construye","Modifica","Depura","Desafío"][i],type:"exercise",...t}))]
 });
 const exercise=(title,body,requirements,starter,solution,checks,hint)=>({title,body,requirements,starter,solution,checks,hint});
 const output=[s.out,"Usa la instrucción de salida propia del lenguaje."], variable=[s.variableCheck,"Declara la variable con la sintaxis de este lenguaje."], condition=[s.ifCheck,"Escribe una condición válida para la regla indicada."], func=[s.functionCheck,"Declara la función con sus parámetros."], returned=[s.returnCheck,"Devuelve el resultado de la función."], collection=[s.collectionCheck,"Declara una colección en este lenguaje."];
 lessons.push(phase("Sintaxis y salida",`Primeros pasos con ${lang.name}: reconoce cómo inicia un programa, declara datos y muestra información.`,`Practica la forma propia de ${lang.name}; el editor revisa estructura y no ejecuta el programa.`,[["Salida",`Usa la sintaxis de ${lang.name} para mostrar texto.`],["Variables","Guarda datos que el programa necesita reutilizar."],["Tipos y valores","La sintaxis varía entre lenguajes."],["Lectura",`Sigue las líneas en orden antes de editar.`]],s.hello,[
  exercise("Muestra un saludo",`Escribe una salida en ${lang.name}.`,["Usa la instrucción de salida indicada.","Incluye el mensaje Hola."],"// Escribe el saludo",s.hello,[output,["Hola","Incluye el saludo solicitado."]],"Usa el ejemplo como guía y conserva las comillas requeridas."),
  exercise("Guarda y muestra un nombre",`Modifica el ejemplo para declarar nombre con el valor Ana y mostrarlo.`,["Declara nombre.","Asigna el texto Ana.","Muestra la variable."],s.hello,s.variable,[variable,output],"Cambia el texto fijo por una variable y conserva la salida."),
  exercise("Depura la salida",`Corrige el fragmento para que muestre Hola en ${lang.name}.`,["Usa la sintaxis de salida correcta.","Escribe el mensaje Hola."],"// Código con error de salida\nprint Hola",s.hello,[output,["Hola","Incluye el mensaje Hola."]],"Compara paréntesis, comillas y terminadores con el ejemplo."),
  exercise("Crea una presentación",`Desde cero, declara nombre como Ana y muestra un saludo que incluya la variable.`,["Declara nombre con el valor Ana.","Muestra una salida.","Usa sintaxis de ${lang.name}."],"// Programa completo aquí",s.variable,[variable,output],"Ordena tu respuesta: declaración y luego salida.")
 ]));
 lessons.push(phase("Decisiones y flujo",`Usa condiciones en ${lang.name} para responder distinto según los datos.`,"Lee la condición, identifica qué valores cumplen la regla y revisa ambos caminos.",[["if","Ejecuta un bloque cuando se cumple una condición."],["else","Define la respuesta alternativa."],[">=","Compara con un mínimo e incluye el límite."],["Trazar","Prueba mentalmente un valor menor y otro mayor."]],s.condition,[
  exercise("Clasifica una edad",`Muestra Mayor de edad si edad es al menos 18; de lo contrario, muestra Menor.`,["Comprueba edad >= 18.","Incluye los dos caminos.","Muestra ambos mensajes."],"// Escribe una condición",s.condition,[condition,output,["Mayor de edad","Incluye la rama positiva."],["Menor de edad","Incluye la rama alternativa."]],"Escribe primero la condición >= 18; añade la salida y el caso contrario."),
  exercise("Cambia el límite",`Edita el ejemplo para mostrar Mayor de edad a partir de 21.`,["Usa edad >= 21.","Conserva una alternativa else.","Muestra los mensajes."],s.condition,s.condition.replace(/18/g,"21"),[[`edad\\s*>=\\s*21`,"Actualiza el límite a 21."],["else","Conserva el caso alternativo."],["Mayor de edad","Incluye la rama positiva."],["Menor de edad","Incluye la alternativa."]],"Cambia solo el valor límite y conserva ambos resultados."),
  exercise("Repara la comparación",`Corrige la condición para usar una comparación de mayor o igual a 18.`,["Compara edad con 18.","Incluye la rama alternativa."],"if (edad = 18) { /* corrige */ }",s.condition,[condition,["else","Incluye else."]],"Asegúrate de usar dos signos de igualdad para comparar solo cuando aplique al lenguaje."),
  exercise("Diseña una decisión",`Construye desde cero una condición que distinga una nota aprobatoria de una no aprobatoria usando 60 como mínimo.`,["Compara nota con 60.","Usa dos caminos.","Muestra Aprobado y Reprobado."],"// Escribe la decisión completa",s.condition.replace(/Mayor de edad/g,"Aprobado").replace(/Menor de edad/g,"Reprobado").replace(/edad/g,"nota").replace(/18/g,"60"),[s.ifCheck.replace(/edad/g,"nota").replace(/18/g,"60"),["else","Incluye la alternativa."],[s.out,"Incluye la sintaxis de salida del lenguaje."],["Aprobado","Incluye el primer resultado."],["Reprobado","Incluye el resultado alternativo."]],"Usa if/else y cambia la condición a nota >= 60."),
 ]));
 lessons.push(phase("Funciones y colecciones",`Organiza tareas reutilizables con funciones y guarda varios valores en colecciones en ${lang.name}.`,"Las funciones reciben datos y pueden devolver un resultado. Las colecciones agrupan valores; recórrelas con un ciclo para procesar cada elemento.",[["Parámetros","Entradas que recibe una función."],["Retorno","Resultado que devuelve la función."],["Colección","Lista o arreglo de varios valores."],["Iteración","Procesa cada elemento sin copiar instrucciones."]],s.func+"\n\n"+s.collection,[
  exercise("Define una función sumar",`Crea una función sumar(a, b) que devuelva a + b en ${lang.name}.`,["Declara sumar con dos parámetros.","Devuelve la suma.","Usa la sintaxis del lenguaje."],"// Define sumar",s.func,[func,returned],"Elige una función corta y revisa si el lenguaje exige anotar tipos."),
  exercise("Modifica la función",`Modifica el cuerpo de la función para multiplicar dos parámetros y devolver el producto.`,["Conserva la función y sus parámetros.","Devuelve a * b.","Usa la sintaxis de ${lang.name}."],s.func,s.func.replace(/\$a\s*\+\s*\$b/g,"$a * $b").replace(/a\s*\+\s*b/g,"a * b"),[func,["return\\s+\\$?a\\s*\\*\\s*\\$?b|\\$?a\\s*\\*\\s*\\$?b","Devuelve el producto."]],"Conserva la firma de la función y cambia + por *."),
  exercise("Depura el retorno",`Corrige la función para que devuelva a + b y no solo muestre datos.`,["Declara una función sumar.","Devuelve a + b."],"// function sumar(a, b) { return a - b; }",s.func,[func,returned],"Una función que calcula un valor necesita return."),
  exercise("Construye una mini herramienta",`Escribe la función sumar y una llamada que muestre el resultado.`,["Define sumar(a, b).","Devuelve a + b.","Llama a la función.","Muestra el resultado."],"// Define, llama y muestra",s.func+"\n"+s.hello,[func,returned,["sumar\\s*\\(","Incluye una llamada a sumar."],output],"Conecta la función a la salida usando el patrón propio del lenguaje.")
 ]));
}
