function playFeedbackSound(correct){
 if(!state.soundEnabled)return;
 const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;
 try{
  audioContext=audioContext||new Audio();if(audioContext.state==="suspended")audioContext.resume();
  const notes=correct?[523.25,659.25,783.99]:[246.94,196];const now=audioContext.currentTime;
  notes.forEach((frequency,index)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),start=now+index*(correct?.09:.12),length=correct?.14:.19;osc.type=correct?"sine":"triangle";osc.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(.11,start+.018);gain.gain.exponentialRampToValueAtTime(.0001,start+length);osc.connect(gain);gain.connect(audioContext.destination);osc.start(start);osc.stop(start+length+.02)});
 }catch(error){/* El audio es opcional y depende del navegador. */}
}
