function checkExercise(p,l,index,code){
 state.attempts++;state.attemptByExercise=state.attemptByExercise||{};const attemptKey=l.id+"-"+index;state.attemptByExercise[attemptKey]=(state.attemptByExercise[attemptKey]||0)+1;saveState();
 const feedback=$("#feedback");const normalized=code.trim();
 if(!normalized){feedback.className="feedback show error";feedback.innerHTML="<strong>Prueba con una primera línea.</strong> El editor está vacío; revisa la pista si necesitas una idea para empezar.";playFeedbackSound(false);animateAnswer(feedback.closest(".exercise-card"),false);return}
 const failures=[];
 (p.checks||[]).forEach(([pattern,message])=>{let ok=false;try{const negative=pattern.startsWith("!");ok=new RegExp(negative?pattern.slice(1):pattern,"im").test(normalized);if(negative)ok=!ok}catch(e){}if(!ok)failures.push(message)});
 const commentOnly=normalized.split("\n").every(line=>!line.trim()||line.trim().startsWith("--")||line.trim().startsWith("//"));
 if(commentOnly)failures.push("Reemplaza los comentarios por código real.");
 if(failures.length===0){
   feedback.className="feedback show success";feedback.innerHTML=`<strong>¡Excelente! Los requisitos principales están cubiertos.</strong>Tu respuesta pasó ${p.checks.length} revisiones de estructura. Ya puedes avanzar; recuerda que esta práctica no ejecuta el código.`;playFeedbackSound(true);animateAnswer(feedback.closest(".exercise-card"),true);
   if(!state.phaseDone[l.id+"-"+index]){markPhase(l.id,index);state.xp+=index===4?25:10;saveState();$("#nextPhase").textContent=index===4?"Terminar sesión ✓":"Fase completada · continuar →";showToast("¡Correcto! +" +(index===4?25:10)+" XP")}
 }else{
   feedback.className="feedback show error";feedback.innerHTML=`<strong>Casi. Vamos paso a paso.</strong>Revisa estos puntos y prueba otra vez:<ul>${failures.map(f=>`<li>${escapeHTML(f)}</li>`).join("")}</ul><p>Tu código sigue en el editor. Usa la pista si te atascas.</p>`;playFeedbackSound(false);animateAnswer(feedback.closest(".exercise-card"),false);
 }
}
function markPhase(id,index){state.phaseDone[id+"-"+index]=true;saveState();const link=document.querySelector(`[data-phase-index="${index}"]`);if(currentLesson&&currentLesson.id===id&&link){link.classList.add("complete");const number=link.querySelector(".phase-n");if(number)number.textContent="✓"}}
