let authRetryTimer;
function showAuthMessage(message,error=false){clearInterval(authRetryTimer);const el=$("#authMessage");el.textContent=message;el.classList.toggle("error",error)}
function showAuthError(error){
 const code=String(error?.code||"").toLowerCase(),message=String(error?.message||"");
 const emailLimit=code==="over_email_send_rate_limit"||/email rate limit exceeded|too many emails have been sent/i.test(message);
 if(emailLimit){
  // Supabase may return an exact per-user cooldown in the message. The built-in
  // project-wide 2/hour quota does not provide a retry timestamp to the client.
  const exactWait=message.match(/after\s+(\d+)\s+seconds?/i);
  if(exactWait){
   let seconds=Number(exactWait[1]);
   const render=()=>{const left=Math.max(0,seconds),el=$("#authMessage");el.textContent=left?`Espera ${left} segundo${left===1?"":"s"} para volver a solicitar el correo.`:"Ya puedes volver a solicitar el correo.";el.classList.add("error");if(seconds<=0){clearInterval(authRetryTimer);return}seconds--};
   render();authRetryTimer=setInterval(render,1000);return;
  }
  showAuthMessage("Se alcanzó el límite de 2 correos por hora de Supabase para todo este proyecto. Supabase no indica cuánto falta exactamente en esta respuesta; vuelve a intentarlo hasta una hora después del último correo enviado por Lazarus Academy. Este límite es compartido por todos los usuarios.",true);return;
 }
 if(error?.status===429||/rate limit|too many requests/i.test(message)){
  showAuthMessage("Se hicieron demasiados intentos seguidos. Espera un momento antes de volver a intentarlo.",true);return;
 }
 showAuthMessage(message||"No se pudo completar la operación.",true);
}
